"""VMT 解析 + 图片尺寸读取（零 GUI 依赖）。"""

import re
import struct
from pathlib import Path


def parse_vmt(path):
    """解析 VMT 文件，提取键值对（键统一小写，值用正斜杠路径）。"""
    with open(path, encoding="utf-8", errors="ignore") as f:
        text = f.read()
    text = re.sub(r"//[^\n]*", "", text)
    result = {}
    for m in re.finditer(
        r'"?(\$[A-Za-z_]\w*)"?\s+(?:"([^"]+)"|([A-Za-z0-9_./\\\-]+))', text
    ):
        key = m.group(1).lower()
        if key not in result:
            val = m.group(2) if m.group(2) is not None else m.group(3)
            result[key] = val.strip().replace("\\", "/")
    return result


def png_size(path):
    """读取 PNG 前 24 字节获取宽高，不是有效 PNG 返回 None。"""
    try:
        with open(path, "rb") as f:
            head = f.read(24)
        if len(head) < 24 or head[:8] != b"\x89PNG\r\n\x1a\n":
            return None
        w, h = struct.unpack(">II", head[16:24])
        return [w, h]
    except OSError:
        return None


def tga_size(path):
    """读取 TGA 头获取宽高，不是有效 TGA 返回 None。"""
    try:
        with open(path, "rb") as f:
            head = f.read(18)
        if len(head) < 18:
            return None
        w = struct.unpack_from("<H", head, 12)[0]
        h = struct.unpack_from("<H", head, 14)[0]
        if not (1 <= w <= 32767 and 1 <= h <= 32767):
            return None
        return [w, h]
    except OSError:
        return None


def image_size(path):
    """根据文件后缀选择对应的尺寸读取函数。"""
    sfx = Path(path).suffix.lower()
    if sfx == ".png":
        return png_size(path)
    if sfx == ".tga":
        return tga_size(path)
    return None
